import{films,processFrame,clampFilm}from './process-films.js?v=20261023-physicscomplete01';
import{processDefaults}from './process-policy.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s),panel=$('.scene-panel'),motion=matchMedia('(prefers-reduced-motion: reduce)');
let active=null,context='',stage=0,position=0,playing=false,previous=0,raf=0,speed=1,lastPhase=-1,showing=false,resumeWhenVisible=false;
const badge=document.createElement('span');badge.id='processLabel';badge.className='live-pill';badge.textContent='Process';badge.hidden=true;$('.scene-top').append(badge);
const button=document.createElement('button');button.id='watchProcess';button.className='scene-button process-open';button.textContent='Inspect model';button.hidden=true;button.setAttribute('aria-controls','processMovie');$('.scene-top').append(button);
const player=document.createElement('section');player.id='processMovie';player.hidden=true;player.setAttribute('aria-labelledby','movieTitle');player.innerHTML='<div class="movie-heading"><div><small>WORKED PROCESS</small><h2 id="movieTitle"></h2></div></div><p class="movie-context">Worked example · your investigation settings stay unchanged.</p><div id="movieArt"></div><p id="movieCaption" aria-live="off"></p><label for="movieScrub">Timeline</label><input id="movieScrub" type="range" min="0" max="1000" value="0" step="1"><div class="movie-controls"><button id="moviePlay" class="primary">Pause</button><button id="movieReplay" class="secondary">Replay</button><button id="moviePrevious" class="secondary" aria-label="Previous process stage">← Stage</button><button id="movieNext" class="secondary" aria-label="Next process stage">Stage →</button><label>Speed<select id="movieSpeed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option></select></label><label class="movie-loop"><input id="movieLoop" type="checkbox" checked> Loop</label></div><p id="movieMotionNote" hidden>Reduced motion: press Play or step through the process.</p><details><summary>Process notes & transcript</summary><p id="movieLimit"></p><ol id="movieTranscript"></ol></details>';panel.append(player);
function stop(){playing=false;cancelAnimationFrame(raf);raf=0;previous=0;$('#moviePlay').textContent=position>=1?'Play again':'Play';$('#moviePlay').setAttribute('aria-pressed','false');$('#movieCaption').setAttribute('aria-live','polite');}
function draw(){if(!active)return;const f=films[active],frame=processFrame(active,position);$('#movieArt').innerHTML=frame.svg;$('#movieScrub').value=String(Math.round(position*1000));$('#movieScrub').setAttribute('aria-valuetext',Math.round(position*100)+'% · '+frame.caption);if(frame.phase!==lastPhase){$('#movieCaption').textContent=`${frame.phase+1} / ${f.steps.length} · ${frame.caption}`;lastPhase=frame.phase;}$('#moviePrevious').disabled=position<=0;$('#movieNext').disabled=position>=1;}
function visible(){return showing&&!player.hidden&&!document.hidden&&player.getClientRects().length>0;}
function animate(t){if(!playing||!active||!visible()){stop();return;}if(previous)position+=Math.min(.1,(t-previous)/1000)*speed/films[active].duration;previous=t;if(position>=1){if($('#movieLoop').checked){position=0;lastPhase=-1;}else{position=1;draw();stop();return;}}draw();raf=requestAnimationFrame(animate);}
function play(){if(!active||!showing)return;cancelAnimationFrame(raf);if(position>=1)position=0;playing=true;previous=0;$('#moviePlay').textContent='Pause';$('#moviePlay').setAttribute('aria-pressed','true');$('#movieCaption').setAttribute('aria-live','off');raf=requestAnimationFrame(animate);}
function displayProcess(on,autoplay=false){stop();showing=!!active&&on;panel.classList.toggle('process-view',showing);player.hidden=!showing;badge.hidden=!showing;button.textContent=showing?'Inspect model':'Show process';button.setAttribute('aria-expanded',String(showing));if(showing){draw();if(autoplay)play();}}
function initialise(defaults){position=0;lastPhase=-1;speed=1;$('#movieSpeed').value='1';$('#movieLoop').checked=defaults.loop;const f=films[active];$('#movieTitle').textContent=f.title;$('#movieLimit').textContent=f.note;$('#movieTranscript').replaceChildren(...f.steps.map(s=>{let li=document.createElement('li');li.textContent=s;return li;}));$('#movieMotionNote').hidden=!motion.matches;displayProcess(true,defaults.autoplay);}
button.onclick=()=>displayProcess(!showing,!motion.matches);
$('#moviePlay').onclick=()=>{resumeWhenVisible=false;playing?stop():play();};$('#movieReplay').onclick=()=>{stop();position=0;lastPhase=-1;draw();play();};$('#movieScrub').oninput=e=>{resumeWhenVisible=false;stop();position=clampFilm(Number(e.target.value)/1000);draw();};$('#movieSpeed').onchange=e=>speed=Number(e.target.value);
function step(direction){resumeWhenVisible=false;stop();let n=films[active].steps.length,index=Math.floor(position*n+1e-7);position=direction>0?(index>=n-1?1:(index+1)/n):Math.max(0,(index-1)/n);draw();}
$('#moviePrevious').onclick=()=>step(-1);$('#movieNext').onclick=()=>step(1);
// The investigation owns its outcome: reveal the selected model when its controls are used.
for(const event of['click','change','input'])document.addEventListener(event,e=>{if(stage===1&&showing&&e.target instanceof Element&&e.target.closest('#activityBody')&&e.target.closest('button,input,select'))displayProcess(false);},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden){resumeWhenVisible=playing;stop();}else if(resumeWhenVisible&&visible()&&!motion.matches){resumeWhenVisible=false;play();}});
motion.addEventListener('change',()=>{$('#movieMotionNote').hidden=!motion.matches;if(motion.matches){resumeWhenVisible=false;stop();}});
export function syncProcessMovie(lesson,nextStage,card=null){const defaults=processDefaults(lesson,nextStage,motion.matches,card),nextContext=lesson?lesson.id+'|'+nextStage:'';stage=nextStage;if(active===defaults.key&&context===nextContext)return;stop();resumeWhenVisible=false;active=defaults.key;context=nextContext;button.hidden=!active;if(!active){displayProcess(false);return;}initialise(defaults);}
